WITH cleaned AS (SELECT id, customer_id, account_type, DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_date_label FROM accounts WHERE status IS NOT NULL AND account_type IN ('CREDIT', 'CHECKING')), not_flagged AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM transactions ch WHERE ch.account_id = s.id AND ch.merchant = 'Starbucks')), eligible AS (SELECT s.* FROM not_flagged s WHERE NOT EXISTS (SELECT 1 FROM transactions c WHERE c.account_id = s.id AND c.account_id IN (3, 16, 34))), eligible_accounts AS (SELECT s.* FROM eligible s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_type IN ('REFUND', 'CREDIT', 'DEBIT'))), not_flagged_accounts AS (SELECT s.* FROM eligible_accounts s WHERE NOT EXISTS (SELECT 1 FROM transactions x WHERE x.account_id = s.id AND x.txn_type NOT IN ('CREDIT', 'FEE'))), grouped AS (SELECT account_type, customer_id, COUNT_IF(account_type = 'SAVINGS') AS savings_events, SIZE(COLLECT_SET(account_type)) AS num_account_types, GROUPING_ID() AS gid FROM not_flagged_accounts GROUP BY GROUPING SETS ((account_type, customer_id), (account_type))) SELECT account_type, customer_id, num_account_types, gid, CASE WHEN account_type RLIKE '^(LOAN|CHECKING)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS account_type_zone FROM grouped ORDER BY account_type DESC
